package com.plaincandle.bankbridge;

import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * The whole payload served over the socket. Immutable and pre-built on the client thread, so the
 * WebSocket threads only ever hand out a reference. They never read the game client.
 */
@Value
public class PlayerData
{
	/** Schema version, so the consuming site can refuse a payload it does not understand. */
	int version;

	/** Epoch millis the bank half of this snapshot was captured. 0 if never captured. */
	long capturedAt;

	String username;

	/** False until the bank has been opened at least once, and no cached snapshot was restored. */
	boolean bankAvailable;

	/** "live" if the bank was read this session, "cache" if restored from disk. */
	String bankSource;

	List<OwnedItem> bank;
	List<OwnedItem> inventory;
	List<OwnedItem> equipment;

	/** Real (unboosted) levels keyed by lowercase skill name. */
	Map<String, Integer> levels;

	/**
	 * Quests, diaries, combat-achievement tiers and a few house varbits. Empty rather than null
	 * when the player has turned unlocks off, or when they have not been read yet, so a consumer
	 * never has to tell "off" apart from "absent" with a null check.
	 */
	Unlocks unlocks;
}

package com.plaincandle.bankbridge;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Holds the most recent snapshot of everything we are willing to serve.
 * <p>
 * The whole design of this plugin lives in this class's threading contract. Every field is written
 * only from the client thread (from item-container / stat events, where reading the game client is
 * legal and free) and read only as an immutable reference from the WebSocket threads. That means a
 * socket request never has to touch the game client, so it can never block it, which is precisely
 * the bug that made the third-party bank-sync plugin unusable.
 */
@Slf4j
@Singleton
public class SnapshotStore
{
	/** 2 added {@code unlocks}: quests, diaries, combat-achievement tiers and house varbits. */
	static final int SCHEMA_VERSION = 2;

	private static final File STORE_DIR = new File(RuneLite.RUNELITE_DIR, "bank-bridge");
	private static final int STORE_VERSION = 1;

	private final Gson gson;
	private final BankBridgeConfig config;

	private volatile List<OwnedItem> bank = Collections.emptyList();
	private volatile long bankCapturedAt = 0L;
	private volatile String bankSource = "none";

	private volatile List<OwnedItem> inventory = Collections.emptyList();
	private volatile List<OwnedItem> equipment = Collections.emptyList();
	private volatile Map<String, Integer> levels = Collections.emptyMap();
	private volatile String username = null;
	private volatile Unlocks unlocks = Unlocks.empty();

	@Inject
	SnapshotStore(Gson gson, BankBridgeConfig config)
	{
		this.gson = gson;
		this.config = config;
	}

	/** The on-disk shape. Deliberately item ids and quantities only: no name, no account hash. */
	@Value
	private static class StoredBank
	{
		int version;
		long capturedAt;
		List<OwnedItem> items;
	}

	// ---------------------------------------------------------------- writes (client thread only)

	void setBank(List<OwnedItem> items, long capturedAt, String source)
	{
		this.bank = items;
		this.bankCapturedAt = capturedAt;
		this.bankSource = source;
	}

	void setInventory(List<OwnedItem> items)
	{
		this.inventory = items;
	}

	void setEquipment(List<OwnedItem> items)
	{
		this.equipment = items;
	}

	void setLevels(Map<String, Integer> levels)
	{
		this.levels = levels;
	}

	void setUsername(String username)
	{
		this.username = username;
	}

	void setUnlocks(Unlocks unlocks)
	{
		this.unlocks = unlocks;
	}

	/** The unlocks currently held, so a caller can skip a store write that changes nothing. */
	Unlocks getUnlocks()
	{
		return unlocks;
	}

	/** Wipes everything that identifies an account. Called on logout and on shutdown. */
	void clear()
	{
		this.bank = Collections.emptyList();
		this.bankCapturedAt = 0L;
		this.bankSource = "none";
		this.inventory = Collections.emptyList();
		this.equipment = Collections.emptyList();
		this.levels = Collections.emptyMap();
		this.username = null;
		this.unlocks = Unlocks.empty();
	}

	// ------------------------------------------------------------------------------------- reads

	boolean isBankAvailable()
	{
		return bankCapturedAt > 0L;
	}

	long getCapturedAt()
	{
		return bankCapturedAt;
	}

	String getUsername()
	{
		return username;
	}

	/**
	 * Builds the payload served to a page. Safe to call from any thread: it only reads volatile
	 * references to already-immutable lists.
	 */
	PlayerData snapshot()
	{
		return new PlayerData(
			SCHEMA_VERSION,
			bankCapturedAt,
			username,
			isBankAvailable(),
			bankSource,
			bank,
			config.shareInventory() ? inventory : Collections.emptyList(),
			config.shareEquipment() ? equipment : Collections.emptyList(),
			config.shareLevels() ? levels : Collections.<String, Integer>emptyMap(),
			config.shareUnlocks() ? unlocks : Unlocks.empty()
		);
	}

	// ---------------------------------------------------------------------- disk (executor only)

	/**
	 * Must not be called from the client thread, because it does blocking file I/O.
	 */
	void persist(long accountHash)
	{
		if (!config.rememberBank() || accountHash == -1L || !isBankAvailable())
		{
			return;
		}

		File target = fileFor(accountHash);
		File tmp = new File(target.getPath() + ".tmp");
		try
		{
			if (!STORE_DIR.exists() && !STORE_DIR.mkdirs())
			{
				log.debug("Could not create {}", STORE_DIR);
				return;
			}

			String json = gson.toJson(new StoredBank(STORE_VERSION, bankCapturedAt, bank));
			Files.write(tmp.toPath(), json.getBytes(StandardCharsets.UTF_8));
			Files.move(tmp.toPath(), target.toPath(), StandardCopyOption.REPLACE_EXISTING);
			log.debug("Persisted {} bank items", bank.size());
		}
		catch (IOException e)
		{
			log.debug("Failed to persist bank snapshot", e);
			//noinspection ResultOfMethodCallIgnored
			tmp.delete();
		}
	}

	/**
	 * Must not be called from the client thread, because it does blocking file I/O.
	 *
	 * @return true if a cached bank was restored, false otherwise.
	 */
	boolean restore(long accountHash)
	{
		if (!config.rememberBank() || accountHash == -1L || isBankAvailable())
		{
			// Never let a cached bank overwrite one we have already read live this session.
			return false;
		}

		File source = fileFor(accountHash);
		if (!source.isFile())
		{
			return false;
		}

		try
		{
			String json = new String(Files.readAllBytes(source.toPath()), StandardCharsets.UTF_8);
			StoredBank stored = gson.fromJson(json, StoredBank.class);
			if (stored == null || stored.getItems() == null || stored.getVersion() != STORE_VERSION)
			{
				return false;
			}

			setBank(Collections.unmodifiableList(stored.getItems()), stored.getCapturedAt(), "cache");
			log.debug("Restored {} cached bank items", stored.getItems().size());
			return true;
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.debug("Failed to restore bank snapshot", e);
			return false;
		}
	}

	void deleteStored(long accountHash)
	{
		if (accountHash == -1L)
		{
			return;
		}
		//noinspection ResultOfMethodCallIgnored
		fileFor(accountHash).delete();
	}

	private static File fileFor(long accountHash)
	{
		return new File(STORE_DIR, "bank-" + Long.toUnsignedString(accountHash) + ".json");
	}
}

package com.plaincandle.bankbridge;

import com.google.inject.Provides;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;

@Slf4j
@PluginDescriptor(
	name = "Bank Bridge",
	description = "Serves your bank, inventory, equipment, levels, quests and diaries to gear-planning sites over a local-only WebSocket",
	tags = {"bank", "sync", "gear", "dps", "websocket", "local", "setup", "inventory", "quest", "diary"}
)
public class BankBridgePlugin extends Plugin
{
	static final String VERSION = "1.2.2";

	/** How long to wait after the last bank change before writing the snapshot to disk. */
	private static final int PERSIST_DEBOUNCE_SECONDS = 5;

	/**
	 * How often to re-read quests, diaries and the rest, in game ticks. 50 ticks is about 30
	 * seconds.
	 * <p>
	 * WHY A POLL AND NOT AN EVENT. The natural trigger is {@code VarbitChanged}, and it is the
	 * wrong one: it fires many times a tick during ordinary play, and each firing would have to
	 * re-read every quest plus 54 varbits to find out whether anything we serve moved. Polling
	 * turns that into one bounded read every 30 seconds, on the client thread, where it costs
	 * array lookups. Completing a quest is not a thing a player does twice a minute, so the
	 * staleness this buys is not worth an event subscription.
	 */
	private static final int UNLOCK_REFRESH_TICKS = 50;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private SnapshotStore store;

	@Inject
	private WebSocketManager webSocketManager;

	@Inject
	private BankBridgeConfig config;

	private final AtomicBoolean persistScheduled = new AtomicBoolean(false);
	private volatile long accountHash = -1L;
	private String lastUsername = null;
	/** Starts due, so the first tick after login reads rather than waiting out the interval. */
	private int ticksSinceUnlockRead = UNLOCK_REFRESH_TICKS;

	@Provides
	BankBridgeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankBridgeConfig.class);
	}

	@Override
	protected void startUp()
	{
		log.debug("Bank Bridge starting");
		webSocketManager.startUp();
	}

	@Override
	protected void shutDown()
	{
		log.debug("Bank Bridge stopping");
		webSocketManager.shutDown();
		store.clear();
		accountHash = -1L;
		lastUsername = null;
		ticksSinceUnlockRead = UNLOCK_REFRESH_TICKS;
	}

	/**
	 * Retries the bind if every port in the range was taken at start-up. A no-op once listening.
	 */
	@Schedule(period = 30, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void ensureSocketActive()
	{
		webSocketManager.ensureActive();
	}

	// ------------------------------------------------------------------------ client-thread reads

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		final ItemContainer container = event.getItemContainer();

		switch (event.getContainerId())
		{
			case InventoryID.BANK:
			{
				List<OwnedItem> items = readContainer(container, true);
				long capturedAt = System.currentTimeMillis();
				store.setBank(items, capturedAt, "live");
				schedulePersist();
				webSocketManager.broadcastBankUpdated(capturedAt);
				break;
			}
			case InventoryID.INV:
				store.setInventory(readContainer(container, false));
				break;
			case InventoryID.WORN:
				store.setEquipment(readContainer(container, false));
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		store.setLevels(readLevels());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();

		if (state == GameState.LOGGED_IN)
		{
			long hash = client.getAccountHash();
			if (hash != accountHash)
			{
				// Switched account (or logged in for the first time): drop everything belonging to
				// the previous one before restoring the new one's cache.
				store.clear();
				accountHash = hash;
				executor.execute(() -> store.restore(hash));
			}
			// Due immediately, whether or not the account changed: a LOGGED_IN transition is also
			// what a world hop and a reconnect look like, and unlocks are cleared on logout.
			ticksSinceUnlockRead = UNLOCK_REFRESH_TICKS;
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			// Back at the login screen the account is gone, so stop serving its data. Hopping is
			// deliberately not handled here: it keeps the same account, and clearing would drop
			// the bank snapshot for no reason.
			store.clear();
			accountHash = -1L;
			lastUsername = null;
			ticksSinceUnlockRead = UNLOCK_REFRESH_TICKS;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		String current = null;
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			Player p = client.getLocalPlayer();
			if (p != null)
			{
				current = p.getName();
			}
			readUnlocksIfDue();
		}

		if (!Objects.equals(lastUsername, current))
		{
			lastUsername = current;
			store.setUsername(current);
		}
	}

	// --------------------------------------------------------------------------------- internals

	/**
	 * Reads an item container into an immutable list. Must run on the client thread.
	 *
	 * @param skipPlaceholders drop bank placeholders, because they are items you do <em>not</em>
	 *                         own, and handing them to a "what do I own" consumer would be a lie.
	 */
	private List<OwnedItem> readContainer(ItemContainer container, boolean skipPlaceholders)
	{
		if (container == null)
		{
			return Collections.emptyList();
		}

		final Item[] items = container.getItems();
		final List<OwnedItem> out = new ArrayList<>(items.length);

		for (Item item : items)
		{
			final int id = item.getId();
			final int qty = item.getQuantity();

			if (id <= 0 || qty <= 0)
			{
				// Empty slot, or a placeholder (which the client models as quantity 0).
				continue;
			}

			if (skipPlaceholders && itemManager.getItemComposition(id).getPlaceholderTemplateId() != -1)
			{
				continue;
			}

			out.add(new OwnedItem(id, qty));
		}

		return Collections.unmodifiableList(out);
	}

	/**
	 * Re-reads quests, diaries, combat achievement tiers and the house varbits every
	 * {@link #UNLOCK_REFRESH_TICKS} ticks. Must run on the client thread.
	 * <p>
	 * The result is only stored when it differs from what is already held, so a page watching the
	 * snapshot is not handed a new object twice a minute for no reason. {@link Unlocks} is a
	 * lombok {@code @Value}, so that comparison is a real deep equality rather than an identity
	 * check that would always be false.
	 */
	private void readUnlocksIfDue()
	{
		if (++ticksSinceUnlockRead < UNLOCK_REFRESH_TICKS)
		{
			return;
		}
		ticksSinceUnlockRead = 0;

		Unlocks fresh = AccountUnlocks.read(client);
		if (!fresh.equals(store.getUnlocks()))
		{
			store.setUnlocks(fresh);
		}
	}

	/** Real, unboosted levels. Must run on the client thread. */
	private Map<String, Integer> readLevels()
	{
		Map<Skill, Integer> raw = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			raw.put(skill, client.getRealSkillLevel(skill));
		}

		Map<String, Integer> levels = new java.util.LinkedHashMap<>(raw.size());
		for (Map.Entry<Skill, Integer> e : raw.entrySet())
		{
			levels.put(e.getKey().getName().toLowerCase(Locale.ROOT), e.getValue());
		}
		return Collections.unmodifiableMap(levels);
	}

	/**
	 * Coalesces a burst of bank changes (depositing an inventory one item at a time fires an event
	 * per item) into a single disk write, off the client thread.
	 */
	private void schedulePersist()
	{
		if (!config.rememberBank())
		{
			return;
		}

		if (persistScheduled.compareAndSet(false, true))
		{
			final long hash = accountHash;
			executor.schedule(() -> {
				persistScheduled.set(false);
				store.persist(hash);
			}, PERSIST_DEBOUNCE_SECONDS, TimeUnit.SECONDS);
		}
	}
}

package com.plaincandle.bankbridge;

import lombok.Value;

@Value
public class OwnedItem
{
	int id;
	int qty;
}

package com.plaincandle.bankbridge;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * THE ONLY PLACE IN THIS PLUGIN THAT READS A VARBIT OR A VARP, and the build enforces that.
 * <p>
 * The plugin's account-safety promise used to be "no var reads at all". Serving quest, diary and
 * combat-achievement completion makes that promise unkeepable, because those states live nowhere
 * else. So the promise was narrowed to the thing it was actually protecting rather than dropped:
 * <ul>
 *   <li>{@code VarClientStr} and {@code VarClientInt} stay banned outright, everywhere, including
 *       here. Those are the client-side vars that carry <em>typed text</em>, which is the only
 *       var family a PIN or a password could ever arrive on.</li>
 *   <li>Server-synced varbits and varps are readable, but only from this file, and only from the
 *       enumerated families {@code accountSafetyCheck} declares. That task fails the build on a
 *       var reference in any other file, and on any constant here outside those families.</li>
 * </ul>
 * That is a narrower guarantee than before and a checkable one: the question "which vars can this
 * plugin see?" has a finite answer that a reader can enumerate from this file in a minute.
 * <p>
 * THREADING. Every method here reads the game client, so every one must be called on the client
 * thread. They return immutable structures, which is what lets {@link SnapshotStore} hand them to
 * the socket threads without those threads ever touching {@link Client}.
 */
final class AccountUnlocks
{
	private AccountUnlocks()
	{
	}

	/**
	 * The twelve achievement-diary regions, each with its four tier varbits in claim order.
	 * <p>
	 * The labels are the game's own region names, not a consuming site's vocabulary: this plugin
	 * serves what the game says and leaves the mapping to whoever asked.
	 * <p>
	 * KARAMJA IS THE ODD ONE and its three lower tiers are worth a note, because the names look
	 * like a mistake. Every other region's constants are {@code <REGION>_DIARY_<TIER>_COMPLETE};
	 * Karamja's easy, medium and hard are {@code ATJUN_EASY_DONE}, {@code ATJUN_MED_DONE} and
	 * {@code ATJUN_HARD_DONE}, and only its elite follows the family. These were not matched on
	 * the name: they were resolved by VALUE against RuneLite's own hand-maintained
	 * {@code Varbits.DIARY_KARAMJA_*} (3578, 3599, 3611), which is the same three ids.
	 */
	private static final Object[][] DIARY_REGIONS = {
		{"Ardougne", new int[]{VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE,
			VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE}},
		{"Desert", new int[]{VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE,
			VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE}},
		{"Falador", new int[]{VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE,
			VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE}},
		{"Fremennik", new int[]{VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE,
			VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE}},
		{"Kandarin", new int[]{VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
			VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE}},
		{"Karamja", new int[]{VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE,
			VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE}},
		{"Kourend & Kebos", new int[]{VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE,
			VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE}},
		{"Lumbridge & Draynor", new int[]{VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE,
			VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE}},
		{"Morytania", new int[]{VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE,
			VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE}},
		{"Varrock", new int[]{VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE,
			VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE}},
		{"Western Provinces", new int[]{VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE,
			VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE}},
		{"Wilderness", new int[]{VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE,
			VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE}},
	};

	/** Diary tier names, in the order a player must claim them. Index-aligned with the arrays above. */
	static final List<String> DIARY_TIERS =
		Collections.unmodifiableList(Arrays.asList("Easy", "Medium", "Hard", "Elite"));

	/** The six combat-achievement tiers, in order. */
	private static final Object[][] CA_TIERS = {
		{"Easy", VarbitID.CA_TIER_STATUS_EASY},
		{"Medium", VarbitID.CA_TIER_STATUS_MEDIUM},
		{"Hard", VarbitID.CA_TIER_STATUS_HARD},
		{"Elite", VarbitID.CA_TIER_STATUS_ELITE},
		{"Master", VarbitID.CA_TIER_STATUS_MASTER},
		{"Grandmaster", VarbitID.CA_TIER_STATUS_GRANDMASTER},
	};

	// WHAT A PLAYER HAS BUILT IN THEIR HOUSE IS NOT READABLE, AND THIS PLUGIN STOPPED PRETENDING.
	//
	// 1.2.0 briefly served three POH varbits (`POH_NEXUS_XERIC`, `POH_NEXUS_DIGSITE`,
	// `POH_JEWELLERYBOX_MULTI`) raw, on the reasoning that a gear planner wants to know whether the
	// house supplies a mounted teleport. Reading them against a real account settled it, and the
	// answer was no:
	//
	//     POH_NEXUS_XERIC          0      on an account with 99 Construction
	//     POH_NEXUS_DIGSITE        0      same account
	//     POH_JEWELLERYBOX_MULTI   19     not a tier index, whatever the name suggests
	//
	// Shane ruled on it directly: "I dont think anything can see what the player has built in their
	// house. It should probably be based on their con level." Corroborated independently by the
	// most thorough profile plugin on the Hub, whose payload carries skills, quests, combat
	// achievement varps, achievement diary tiers and items, and NO house data of any kind.
	//
	// So three varbits nobody can interpret are removed rather than shipped with a disclaimer.
	// Serving a value whose meaning is unknown is data collected because it was available, and a
	// consumer that wants to know whether a house has a feature should ask the Construction level,
	// which this plugin already serves.

	// ------------------------------------------------------------------ the two reads, in one place

	private static int varbit(Client client, int id)
	{
		return client.getVarbitValue(id);
	}

	private static int varp(Client client, int id)
	{
		return client.getVarpValue(id);
	}

	// --------------------------------------------------------------------------------- the payload

	/** Reads everything at once. Client thread only. */
	static Unlocks read(Client client)
	{
		return new Unlocks(
			quests(client),
			questIds(),
			varp(client, VarPlayerID.QP),
			completedDiaries(client),
			combatAchievementTiers(client));
	}

	/**
	 * Quest name to the game's own quest id, for every quest this client knows.
	 *
	 * A SECOND ANCHOR, NOT A REPLACEMENT. A consumer joins on the NAME, because the wiki is
	 * name-keyed and nothing on the wiki carries this id. But a name is the thing that moves: if a
	 * quest is renamed, a name-only join silently drops the row and looks like a quest the account
	 * has not done. With the id beside it, the same row reads as "renamed", which is a different
	 * and fixable answer.
	 * <p>
	 * Free to serve and free of any new API: {@code Quest.getId()} is a plain enum accessor on
	 * values this class already walks. Not read from the client at all, so no var and no script.
	 */
	private static Map<String, Integer> questIds()
	{
		final List<Quest> sorted = new ArrayList<>(Arrays.asList(Quest.values()));
		sorted.sort(Comparator.comparing(Quest::getName));

		final Map<String, Integer> out = new LinkedHashMap<>();
		for (Quest quest : sorted)
		{
			out.put(quest.getName(), quest.getId());
		}
		return Collections.unmodifiableMap(out);
	}

	/**
	 * EVERY quest this client knows, name to state, sorted by name. Not just the finished ones.
	 * <p>
	 * The first version of this served finished quests only, on the reasoning that a consumer asks
	 * "can this account do X" and an in-progress quest answers that the same way an unstarted one
	 * does. That reasoning was wrong, and measuring it against a real consumer is what showed it.
	 * <p>
	 * A consumer holds its own list of quests, and the two vocabularies do not match. Measured
	 * against one such list of 208 rows: 187 names matched exactly, 9 more were Recipe for
	 * Disaster subquests spelled differently, 14 were quests this client knows and it does not,
	 * and 12 of its rows are ones this client cannot name at all: eleven that are not quests here
	 * (Barbarian Firemaking, Knight Waves Training Grounds, Tutorial Island and the rest) plus one
	 * Recipe for Disaster subquest whose two spellings share no words. WITH ONLY THE FINISHED
	 * LIST, A CONSUMER CANNOT TELL "you have not done this" APART FROM "I do not have a name for
	 * this", so it reads all 12 as incomplete.
	 * <p>
	 * WHAT THAT COSTS TODAY IS SMALL, AND SAYING SO MATTERS MORE THAN THE ARGUMENT FOR THE CHANGE.
	 * Measured on that consumer: the naive reading loses exactly those 12 rows and then nothing
	 * else. Zero items become unobtainable and zero achievement diary tiers are lost, because every
	 * row that depends on the 12 is itself a quest this client CAN name and report directly. An
	 * earlier version of this comment claimed a fully completed account would be told it had not
	 * done Dragon Slayer II; that was wrong, and measuring it rather than reasoning about it is
	 * what showed it.
	 * <p>
	 * The change is still the right one, for the reason that survives the correction: serving the
	 * vocabulary keeps the error BOUNDED as the two lists drift. A name absent from this map is one
	 * this client has no concept of, so a consumer falls back to its own reasoning for that row
	 * instead of calling it undone, and the names it could not place tell it where it has fallen
	 * behind. A fixed list of exceptions on the consuming side would go stale the moment a new
	 * quest ships, and this client already knows fourteen that consumer does not.
	 * <p>
	 * The names are RuneLite's, which are the game's: a subquest arrives as its own entry
	 * ("Recipe for Disaster - Another Cook's Quest") rather than folded into its parent.
	 */
	private static Map<String, String> quests(Client client)
	{
		final List<Quest> sorted = new ArrayList<>(Arrays.asList(Quest.values()));
		sorted.sort(Comparator.comparing(Quest::getName));

		final Map<String, String> out = new LinkedHashMap<>();
		for (Quest quest : sorted)
		{
			final QuestState state = quest.getState(client);
			out.put(quest.getName(), state == null ? QuestState.NOT_STARTED.name() : state.name());
		}
		return Collections.unmodifiableMap(out);
	}

	/**
	 * Region to the diary tiers completed there, in claim order.
	 * <p>
	 * A tier reads as complete when its varbit is non-zero. Tiers are NOT inferred from one
	 * another: each is reported from its own varbit, so a consumer that believes tiers are claimed
	 * in order can check that belief against this rather than have it baked in here.
	 */
	private static Map<String, List<String>> completedDiaries(Client client)
	{
		final Map<String, List<String>> out = new LinkedHashMap<>();
		for (Object[] row : DIARY_REGIONS)
		{
			final String region = (String) row[0];
			final int[] varbits = (int[]) row[1];
			final List<String> tiers = new ArrayList<>(4);
			for (int i = 0; i < varbits.length; i++)
			{
				if (varbit(client, varbits[i]) > 0)
				{
					tiers.add(DIARY_TIERS.get(i));
				}
			}
			out.put(region, Collections.unmodifiableList(tiers));
		}
		return Collections.unmodifiableMap(out);
	}

	/**
	 * Tier name to the raw tier varbit.
	 * <p>
	 * STILL RAW, THOUGH THE ENCODING IS NOW PARTLY KNOWN. Read against a real account with the
	 * first two tiers done: {@code Easy 2, Medium 2, Hard 0, Elite 0, Master 0, Grandmaster 0}, so
	 * <b>2 means completed and 0 means not</b>. No tier read 1, so whatever an in-progress tier
	 * reports is still unobserved, and a boolean would have to guess at it. An integer whose
	 * meaning a consumer can look up beats a boolean that hides the case nobody has seen.
	 */
	private static Map<String, Integer> combatAchievementTiers(Client client)
	{
		final Map<String, Integer> out = new LinkedHashMap<>();
		for (Object[] row : CA_TIERS)
		{
			out.put((String) row[0], varbit(client, (Integer) row[1]));
		}
		return Collections.unmodifiableMap(out);
	}
}

package com.plaincandle.bankbridge.ws;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * A minimal WebSocket server built on {@link ServerSocket}, with no third party dependency.
 * <p>
 * Binds to the loopback interface only. Nothing on the network can reach this, by construction:
 * an explicit 127.0.0.1 bind rather than a wildcard bind plus a firewall rule.
 */
public class WSWebsocketServer
{
	private static final int BACKLOG = 8;

	private final InetSocketAddress address;
	private final WSHandler handler;
	private final Set<WSConnection> connections = ConcurrentHashMap.newKeySet();
	private final AtomicInteger connectionCounter = new AtomicInteger();

	private volatile ServerSocket serverSocket;
	private volatile boolean running;
	private boolean daemon = false;

	public WSWebsocketServer(int port, WSHandler handler)
	{
		this.address = new InetSocketAddress("127.0.0.1", port);
		this.handler = handler;
	}

	public void setDaemon(boolean daemon)
	{
		this.daemon = daemon;
	}

	public InetSocketAddress getAddress()
	{
		return address;
	}

	public int getPort()
	{
		return address.getPort();
	}

	/**
	 * Returns immediately. The bind happens on the accept thread, so a busy port surfaces as
	 * {@code onError(null, ex)} rather than as an exception on the caller: that asynchronous
	 * failure is what drives the port fallback across the 37767-37776 range.
	 */
	public void start()
	{
		running = true;
		Thread t = new Thread(this::acceptLoop, "bank-bridge-accept-" + getPort());
		t.setDaemon(daemon);
		t.start();
	}

	/**
	 * Closes the listener and every live connection.
	 * <p>
	 * Returns without waiting on the accept thread. Closing the server socket releases the port
	 * immediately and unblocks {@code accept()}, so the thread winds down on its own; not waiting
	 * also keeps this safe to call from the accept thread itself, which happens when
	 * {@code onError} drives the port fallback.
	 */
	public void stop()
	{
		running = false;

		ServerSocket ss = this.serverSocket;
		if (ss != null)
		{
			try
			{
				ss.close();
			}
			catch (IOException ignored)
			{
				// Already closed, or never opened.
			}
		}

		for (WSConnection conn : connections)
		{
			conn.closeQuietly(WSConnection.CLOSE_NORMAL, "server stopping", false);
		}
		connections.clear();
	}

	/** Sends to every open connection. A failing peer is skipped, never fatal to the others. */
	public void broadcast(String text)
	{
		for (WSConnection conn : connections)
		{
			if (conn.isOpen())
			{
				conn.send(text);
			}
		}
	}

	private void acceptLoop()
	{
		ServerSocket ss;
		try
		{
			ss = new ServerSocket();
			// Must stay false. On Windows SO_REUSEADDR lets a second bind succeed on a port that is
			// already listening, which would silently defeat the whole port fallback: we would
			// "bind" on top of WikiSync instead of stepping to the next port.
			ss.setReuseAddress(false);
			ss.bind(address, BACKLOG);
		}
		catch (IOException e)
		{
			handler.onError(null, e);
			return;
		}

		this.serverSocket = ss;
		handler.onStart();

		while (running)
		{
			Socket socket;
			try
			{
				socket = ss.accept();
			}
			catch (IOException e)
			{
				if (running)
				{
					// The listener itself is broken. Report it and let the handler rebind rather
					// than spinning on a socket that will keep failing.
					handler.onError(null, e);
				}
				return;
			}

			try
			{
				socket.setTcpNoDelay(true);
				WSConnection conn = new WSConnection(socket, handler);
				connections.add(conn);

				Thread t = new Thread(() -> {
					try
					{
						conn.serve();
					}
					finally
					{
						connections.remove(conn);
					}
				}, "bank-bridge-conn-" + connectionCounter.incrementAndGet());
				t.setDaemon(true);
				t.start();
			}
			catch (IOException e)
			{
				// One peer failed to set up. That is not a server fault, so it must NOT be reported
				// as onError(null, ...): that means "the listener is broken, rebind" and would move
				// the whole server to another port over a single bad connection.
				try
				{
					socket.close();
				}
				catch (IOException ignored)
				{
					// Nothing left to do with it.
				}
			}
		}
	}
}

package com.plaincandle.bankbridge.ws;

import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.net.Socket;
import java.net.SocketAddress;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.Locale;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * One accepted WebSocket connection: the RFC 6455 handshake, frame decoding, frame encoding and
 * close semantics, over a plain {@link Socket}.
 * <p>
 * This is written against the JDK alone rather than a WebSocket library. That is a deliberate
 * trade: the protocol surface we actually need is small (text frames, ping, close, all inbound
 * traffic from a browser on loopback), and having no third party dependency is what lets the plugin
 * build as {@code build=standard} on the Plugin Hub, which is what gets it reviewed.
 * <p>
 * The rules that matter and are easy to get wrong, all from RFC 6455 section 5:
 * <ul>
 *   <li>every client to server frame is masked, and a server MUST reject an unmasked one</li>
 *   <li>every server to client frame is NOT masked</li>
 *   <li>control frames are never fragmented and never exceed 125 bytes of payload</li>
 *   <li>a message can arrive split across a data frame plus continuation frames</li>
 * </ul>
 */
public final class WSConnection
{
	/** RFC 6455 section 1.3. Concatenated with the client key to derive the accept token. */
	private static final String MAGIC = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";

	private static final int OP_CONTINUATION = 0x0;
	private static final int OP_TEXT = 0x1;
	private static final int OP_BINARY = 0x2;
	private static final int OP_CLOSE = 0x8;
	private static final int OP_PING = 0x9;
	private static final int OP_PONG = 0xA;

	public static final int CLOSE_NORMAL = 1000;
	public static final int CLOSE_PROTOCOL_ERROR = 1002;
	public static final int CLOSE_UNSUPPORTED_DATA = 1003;
	public static final int CLOSE_TOO_LARGE = 1009;

	/**
	 * Requests are a few dozen bytes of JSON. This is the ceiling on what an unauthenticated peer
	 * can make us buffer, so it is set to the smallest number that cannot plausibly be hit.
	 */
	private static final int MAX_MESSAGE_BYTES = 64 * 1024;

	/** A peer that connects and then says nothing must not hold a thread forever. */
	private static final int HANDSHAKE_TIMEOUT_MS = 10_000;

	private final Socket socket;
	private final DataInputStream in;
	private final OutputStream out;
	private final WSHandler handler;

	/** Serialises frame writes. Sends arrive from the manager's executor and from broadcast. */
	private final Object writeLock = new Object();

	private final AtomicBoolean closeReported = new AtomicBoolean(false);
	private volatile boolean open = false;
	private volatile Handshake handshake;

	WSConnection(Socket socket, WSHandler handler) throws IOException
	{
		this.socket = socket;
		this.handler = handler;
		this.in = new DataInputStream(new java.io.BufferedInputStream(socket.getInputStream(), 8192));
		this.out = socket.getOutputStream();
	}

	public boolean isOpen()
	{
		return open;
	}

	public String getResourceDescriptor()
	{
		Handshake h = this.handshake;
		return h == null ? null : h.getResourceDescriptor();
	}

	public SocketAddress getLocalSocketAddress()
	{
		return socket.getLocalSocketAddress();
	}

	/**
	 * Sends a text message as a single unfragmented frame. Silently does nothing on a closed
	 * connection, which is what lets the manager fire and forget from its executor.
	 */
	public void send(String text)
	{
		if (!open)
		{
			return;
		}

		byte[] payload = text.getBytes(StandardCharsets.UTF_8);
		try
		{
			synchronized (writeLock)
			{
				writeFrameHeader(OP_TEXT, payload.length);
				out.write(payload);
				out.flush();
			}
		}
		catch (IOException e)
		{
			closeQuietly(CLOSE_NORMAL, "write failed", false);
		}
	}

	public void close()
	{
		closeQuietly(CLOSE_NORMAL, "", false);
	}

	public void close(int code, String reason)
	{
		closeQuietly(code, reason, false);
	}

	// ------------------------------------------------------------------------------- server driver

	/**
	 * Runs the connection to completion on the calling thread: handshake, then the read loop.
	 * Returns once the connection is finished.
	 */
	void serve()
	{
		try
		{
			socket.setSoTimeout(HANDSHAKE_TIMEOUT_MS);
			Handshake h = Handshake.read(in);

			String failure = validate(h);
			if (failure != null)
			{
				refuse(failure);
				return;
			}

			this.handshake = h;
			accept(h.getFieldValue("Sec-WebSocket-Key"));
			this.open = true;

			// The handshake is bounded; the session that follows is not, and a browser tab can sit
			// idle for hours between requests.
			socket.setSoTimeout(0);

			handler.onOpen(this, h);

			readLoop();
		}
		catch (IOException e)
		{
			// A peer hanging up is the normal way a connection ends, not an error worth surfacing.
			closeQuietly(CLOSE_NORMAL, "", true);
		}
		catch (RuntimeException e)
		{
			handler.onError(this, e);
			closeQuietly(CLOSE_PROTOCOL_ERROR, "internal error", false);
		}
		finally
		{
			closeQuietly(CLOSE_NORMAL, "", false);
		}
	}

	/** @return null when the request is a valid RFC 6455 upgrade, otherwise why it is not */
	private String validate(Handshake h)
	{
		if (!"GET".equals(h.getMethod()))
		{
			return "Method Not Allowed";
		}

		if (!h.getFieldValue("Upgrade").toLowerCase(Locale.ROOT).contains("websocket"))
		{
			return "Expected Upgrade: websocket";
		}

		if (!h.getFieldValue("Connection").toLowerCase(Locale.ROOT).contains("upgrade"))
		{
			return "Expected Connection: Upgrade";
		}

		if (!"13".equals(h.getFieldValue("Sec-WebSocket-Version")))
		{
			return "Unsupported Sec-WebSocket-Version";
		}

		if (h.getFieldValue("Sec-WebSocket-Key").isEmpty())
		{
			return "Missing Sec-WebSocket-Key";
		}

		return null;
	}

	private void accept(String key) throws IOException
	{
		String token = Base64.getEncoder().encodeToString(sha1(key + MAGIC));
		String response = "HTTP/1.1 101 Switching Protocols\r\n"
			+ "Upgrade: websocket\r\n"
			+ "Connection: Upgrade\r\n"
			+ "Sec-WebSocket-Accept: " + token + "\r\n"
			+ "\r\n";
		out.write(response.getBytes(StandardCharsets.ISO_8859_1));
		out.flush();
	}

	/** Turns down a request that never became a WebSocket, with an HTTP response and no frames. */
	private void refuse(String reason) throws IOException
	{
		String body = reason + "\n";
		String response = "HTTP/1.1 400 Bad Request\r\n"
			+ "Content-Type: text/plain; charset=utf-8\r\n"
			+ "Content-Length: " + body.getBytes(StandardCharsets.UTF_8).length + "\r\n"
			+ "Connection: close\r\n"
			+ "\r\n"
			+ body;
		out.write(response.getBytes(StandardCharsets.UTF_8));
		out.flush();
	}

	private static byte[] sha1(String s)
	{
		try
		{
			return MessageDigest.getInstance("SHA-1").digest(s.getBytes(StandardCharsets.UTF_8));
		}
		catch (NoSuchAlgorithmException e)
		{
			// SHA-1 is required of every JVM by the MessageDigest spec.
			throw new IllegalStateException("SHA-1 unavailable", e);
		}
	}

	// ------------------------------------------------------------------------------------ decoding

	private void readLoop() throws IOException
	{
		ByteArrayOutputStream message = null;
		int messageOpcode = -1;

		while (open)
		{
			int b0 = in.readUnsignedByte();
			boolean fin = (b0 & 0x80) != 0;
			if ((b0 & 0x70) != 0)
			{
				// RSV1-3 are only meaningful with a negotiated extension, and we negotiate none.
				closeQuietly(CLOSE_PROTOCOL_ERROR, "reserved bits set", false);
				return;
			}
			int opcode = b0 & 0x0F;

			int b1 = in.readUnsignedByte();
			boolean masked = (b1 & 0x80) != 0;
			long length = b1 & 0x7F;

			if (length == 126)
			{
				length = in.readUnsignedShort();
			}
			else if (length == 127)
			{
				length = in.readLong();
				if (length < 0)
				{
					closeQuietly(CLOSE_TOO_LARGE, "payload length overflow", false);
					return;
				}
			}

			if (!masked)
			{
				// Not a nicety: an unmasked client frame is how cache poisoning attacks against
				// intermediaries work, so the RFC requires the server to fail the connection.
				closeQuietly(CLOSE_PROTOCOL_ERROR, "client frames must be masked", false);
				return;
			}

			if (length > MAX_MESSAGE_BYTES)
			{
				closeQuietly(CLOSE_TOO_LARGE, "frame too large", false);
				return;
			}

			byte[] mask = new byte[4];
			in.readFully(mask);

			byte[] payload = new byte[(int) length];
			in.readFully(payload);
			for (int i = 0; i < payload.length; i++)
			{
				payload[i] ^= mask[i & 3];
			}

			if (opcode >= OP_CLOSE)
			{
				if (!fin || payload.length > 125)
				{
					closeQuietly(CLOSE_PROTOCOL_ERROR, "bad control frame", false);
					return;
				}

				if (opcode == OP_CLOSE)
				{
					int code = payload.length >= 2
						? ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF)
						: CLOSE_NORMAL;
					String reason = payload.length > 2
						? new String(payload, 2, payload.length - 2, StandardCharsets.UTF_8)
						: "";
					closeQuietly(code, reason, true);
					return;
				}
				else if (opcode == OP_PING)
				{
					writeControl(OP_PONG, payload);
				}
				// A pong is either an answer to a ping we never send, or unsolicited. Either way
				// there is nothing to do with it.
				continue;
			}

			if (opcode == OP_CONTINUATION)
			{
				if (message == null)
				{
					closeQuietly(CLOSE_PROTOCOL_ERROR, "continuation without a start frame", false);
					return;
				}
			}
			else
			{
				if (message != null)
				{
					closeQuietly(CLOSE_PROTOCOL_ERROR, "new message before the previous one finished", false);
					return;
				}
				messageOpcode = opcode;
				message = new ByteArrayOutputStream();
			}

			if (message.size() + payload.length > MAX_MESSAGE_BYTES)
			{
				closeQuietly(CLOSE_TOO_LARGE, "message too large", false);
				return;
			}
			message.write(payload);

			if (!fin)
			{
				continue;
			}

			byte[] complete = message.toByteArray();
			message = null;

			if (messageOpcode == OP_BINARY)
			{
				// The protocol is JSON over text frames. Refusing binary outright beats guessing.
				closeQuietly(CLOSE_UNSUPPORTED_DATA, "binary frames are not supported", false);
				return;
			}

			handler.onMessage(this, new String(complete, StandardCharsets.UTF_8));
		}
	}

	// ------------------------------------------------------------------------------------ encoding

	/** Caller must hold {@link #writeLock}. Server frames are never masked (RFC 6455 5.1). */
	private void writeFrameHeader(int opcode, int length) throws IOException
	{
		out.write(0x80 | opcode);

		if (length < 126)
		{
			out.write(length);
		}
		else if (length <= 0xFFFF)
		{
			out.write(126);
			out.write((length >>> 8) & 0xFF);
			out.write(length & 0xFF);
		}
		else
		{
			out.write(127);
			// A 64 bit length whose top four bytes are always zero: an int cannot reach them.
			out.write(0);
			out.write(0);
			out.write(0);
			out.write(0);
			out.write((length >>> 24) & 0xFF);
			out.write((length >>> 16) & 0xFF);
			out.write((length >>> 8) & 0xFF);
			out.write(length & 0xFF);
		}
	}

	private void writeControl(int opcode, byte[] payload)
	{
		try
		{
			synchronized (writeLock)
			{
				out.write(0x80 | opcode);
				out.write(payload.length);
				out.write(payload);
				out.flush();
			}
		}
		catch (IOException ignored)
		{
			// The socket is going away; the close path below handles it.
		}
	}

	/**
	 * Ends the connection once. Sends a close frame if the session ever opened, tears down the
	 * socket, and reports {@code onClose} exactly one time no matter how many paths race here.
	 *
	 * @param remote true when the peer initiated the close
	 */
	void closeQuietly(int code, String reason, boolean remote)
	{
		if (!closeReported.compareAndSet(false, true))
		{
			return;
		}

		boolean wasOpen = open;
		open = false;

		if (wasOpen)
		{
			byte[] reasonBytes = reason == null ? new byte[0] : reason.getBytes(StandardCharsets.UTF_8);
			// 125 byte control frame budget, minus the two byte status code.
			int reasonLength = Math.min(reasonBytes.length, 123);
			byte[] payload = new byte[2 + reasonLength];
			payload[0] = (byte) ((code >>> 8) & 0xFF);
			payload[1] = (byte) (code & 0xFF);
			System.arraycopy(reasonBytes, 0, payload, 2, reasonLength);
			writeControl(OP_CLOSE, payload);
		}

		try
		{
			socket.close();
		}
		catch (IOException ignored)
		{
			// Already gone.
		}

		if (wasOpen)
		{
			handler.onClose(this, code, reason, remote);
		}
	}
}

package com.plaincandle.bankbridge.ws;

import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * The opening HTTP request of a WebSocket connection, parsed.
 * <p>
 * This exists so the origin check has something to read. The header map is the security surface of
 * this plugin: {@code Origin} is what tells us which website is on the other end, so parsing it has
 * to be boring and strict rather than clever.
 */
public final class Handshake
{
	/**
	 * A handshake is a few hundred bytes. Anything larger is not a browser, and reading it
	 * unbounded would let an unauthenticated peer grow our heap before we ever check who it is.
	 */
	private static final int MAX_HANDSHAKE_BYTES = 8192;

	private final String method;
	private final String resourceDescriptor;
	private final Map<String, String> fields;

	private Handshake(String method, String resourceDescriptor, Map<String, String> fields)
	{
		this.method = method;
		this.resourceDescriptor = resourceDescriptor;
		this.fields = fields;
	}

	public String getMethod()
	{
		return method;
	}

	/** The request target, e.g. {@code "/"}. */
	public String getResourceDescriptor()
	{
		return resourceDescriptor;
	}

	/**
	 * @return the header value, or an empty string when the header is absent. Never null, so callers
	 *         cannot accidentally treat "absent" as "allowed" by skipping a null check.
	 */
	public String getFieldValue(String name)
	{
		String v = fields.get(name.toLowerCase(Locale.ROOT));
		return v == null ? "" : v;
	}

	public boolean hasField(String name)
	{
		return fields.containsKey(name.toLowerCase(Locale.ROOT));
	}

	/**
	 * Reads the request line and headers off the wire, stopping at the blank line that ends them.
	 * Deliberately reads one byte at a time: the bytes after the blank line are WebSocket frames,
	 * not HTTP, so a block read could swallow the start of the first frame.
	 *
	 * @throws IOException if the peer disconnects, sends more than {@link #MAX_HANDSHAKE_BYTES}, or
	 *                     sends something that is not a well formed HTTP request head
	 */
	public static Handshake read(InputStream in) throws IOException
	{
		byte[] buf = new byte[MAX_HANDSHAKE_BYTES];
		int len = 0;

		while (true)
		{
			int b = in.read();
			if (b < 0)
			{
				throw new EOFException("Connection closed during handshake");
			}

			if (len == buf.length)
			{
				throw new IOException("Handshake exceeded " + MAX_HANDSHAKE_BYTES + " bytes");
			}
			buf[len++] = (byte) b;

			if (len >= 4
				&& buf[len - 4] == '\r' && buf[len - 3] == '\n'
				&& buf[len - 2] == '\r' && buf[len - 1] == '\n')
			{
				break;
			}
		}

		// ISO-8859-1 rather than UTF-8: HTTP/1.1 header bytes are latin-1, and decoding them as
		// UTF-8 would let malformed input turn into replacement characters instead of failing.
		String head = new String(buf, 0, len, StandardCharsets.ISO_8859_1);
		String[] lines = head.split("\r\n");
		if (lines.length == 0 || lines[0].isEmpty())
		{
			throw new IOException("Empty request line");
		}

		String[] requestLine = lines[0].split(" ");
		if (requestLine.length < 3)
		{
			throw new IOException("Malformed request line: " + lines[0]);
		}

		Map<String, String> fields = new HashMap<>();
		for (int i = 1; i < lines.length; i++)
		{
			String line = lines[i];
			if (line.isEmpty())
			{
				continue;
			}

			int colon = line.indexOf(':');
			if (colon <= 0)
			{
				throw new IOException("Malformed header: " + line);
			}

			String name = line.substring(0, colon).trim().toLowerCase(Locale.ROOT);
			String value = line.substring(colon + 1).trim();
			// Last one wins. A duplicated Origin is not something a browser does, and merging them
			// would only create a string that parses as neither host.
			fields.put(name, value);
		}

		return new Handshake(requestLine[0], requestLine[1], fields);
	}
}

package com.plaincandle.bankbridge.ws;

/**
 * Callback surface for {@link WSWebsocketServer}, so the server class stays a thin transport and all
 * of the policy (who is allowed to connect, what a request means) lives in a testable, injectable
 * manager.
 */
public interface WSHandler
{
	default void onOpen(WSConnection conn, Handshake handshake) {}

	default void onClose(WSConnection conn, int code, String reason, boolean remote) {}

	default void onMessage(WSConnection conn, String message) {}

	/** A null connection means the failure is the server's own, almost always a busy port. */
	default void onError(WSConnection conn, Exception ex) {}

	default void onStart() {}
}

package com.plaincandle.bankbridge;

import com.google.common.collect.ImmutableSet;
import com.google.common.util.concurrent.ThreadFactoryBuilder;
import com.google.gson.Gson;
import com.plaincandle.bankbridge.messages.Request;
import com.plaincandle.bankbridge.messages.response.BankUpdated;
import com.plaincandle.bankbridge.messages.response.ErrorResponse;
import com.plaincandle.bankbridge.messages.response.GetBank;
import com.plaincandle.bankbridge.messages.response.Hello;
import com.plaincandle.bankbridge.ws.Handshake;
import com.plaincandle.bankbridge.ws.WSConnection;
import com.plaincandle.bankbridge.ws.WSHandler;
import com.plaincandle.bankbridge.ws.WSWebsocketServer;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.HashSet;
import java.util.Locale;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Owns the local WebSocket server: its lifecycle, its port, who is allowed to talk to it, and how
 * requests are answered.
 * <p>
 * Note what this class does <em>not</em> have: any reference to {@code Client} or
 * {@code ClientThread}. Requests are answered purely out of {@link SnapshotStore}, so no socket
 * traffic can ever reach the game client, let alone block it.
 */
@Slf4j
@Singleton
public class WebSocketManager implements WSHandler
{
	/**
	 * The same range WikiSync uses. Sharing the convention means a page can scan one port range and
	 * find whichever of these plugins the user has installed.
	 */
	private static final int PORT_MIN = 37767;
	private static final int PORT_MAX = 37776;

	/**
	 * The security boundary. A WebSocket is not subject to the same-origin policy, so without this
	 * check, ANY website you happened to have open could read your bank. Browsers set Origin on
	 * every WebSocket handshake and it cannot be forged by page JavaScript.
	 */
	private static final Set<String> ALLOWED_ORIGIN_HOSTS = ImmutableSet.of(
		"osrs.plaincandle.dev",
		"localhost",
		"127.0.0.1"
	);

	private final AtomicBoolean serverActive = new AtomicBoolean(false);

	private final Gson gson;
	private final SnapshotStore store;
	private final BankBridgeConfig config;

	private int nextPort;
	private WSWebsocketServer server;

	private static final ExecutorService executorService = Executors.newSingleThreadExecutor(
		new ThreadFactoryBuilder().setDaemon(true).setNameFormat("bank-bridge-ws-%d").build());

	@Inject
	WebSocketManager(Gson gson, SnapshotStore store, BankBridgeConfig config)
	{
		this.gson = gson;
		this.store = store;
		this.config = config;
	}

	public void startUp()
	{
		this.nextPort = PORT_MIN;
		// In case we are resuming from a bad state, drop anything still bound.
		stopServer();
		ensureActive();
	}

	public void shutDown()
	{
		log.debug("Shutting down Bank Bridge socket. Active = {}", serverActive.getPlain());
		stopServer();
	}

	/**
	 * Starts a server if one is not already running. Designed to be called on a schedule, so it is a
	 * no-op on most invocations, and is what recovers the socket if every port was busy at start-up
	 * and one later frees up.
	 */
	public void ensureActive()
	{
		if (!serverActive.compareAndExchange(false, true))
		{
			this.server = new WSWebsocketServer(this.nextPort++, this);
			this.server.start();
			log.debug("Bank Bridge socket attempting to bind: {}", this.server.getAddress());
			if (this.nextPort > PORT_MAX)
			{
				this.nextPort = PORT_MIN;
			}
		}
	}

	/** Tells every connected page that the bank changed. Never carries the payload itself. */
	public void broadcastBankUpdated(long capturedAt)
	{
		if (!serverActive.get())
		{
			return;
		}
		final String json = gson.toJson(new BankUpdated(capturedAt));
		executorService.submit(() -> {
			WSWebsocketServer s = this.server;
			if (s != null)
			{
				s.broadcast(json);
			}
		});
	}

	@Override
	public void onOpen(WSConnection conn, Handshake handshake)
	{
		String requestPath = conn.getResourceDescriptor();
		String origin = handshake.getFieldValue("origin");
		log.debug("Bank Bridge connection attempt. path={}, origin={}", requestPath, origin);

		if (!Objects.equals(requestPath, "/"))
		{
			log.debug("Rejecting unknown request path: {}", requestPath);
			conn.close();
			return;
		}

		if (!isOriginAllowed(origin))
		{
			log.debug("Rejecting unauthorised origin: {}", origin);
			conn.close();
			return;
		}

		send(conn, new Hello(
			BankBridgePlugin.VERSION,
			SnapshotStore.SCHEMA_VERSION,
			store.getUsername(),
			store.isBankAvailable(),
			store.getCapturedAt()
		));
	}

	@Override
	public void onMessage(WSConnection conn, String message)
	{
		Request request;
		try
		{
			request = gson.fromJson(message, Request.class);
		}
		catch (RuntimeException e)
		{
			log.debug("Unparseable request", e);
			send(conn, new ErrorResponse(0, "Malformed request"));
			return;
		}

		if (request == null || request.get_wsType() == null)
		{
			send(conn, new ErrorResponse(request == null ? 0 : request.getSequenceId(), "Unknown request type"));
			return;
		}

		switch (request.get_wsType())
		{
			case GetBank:
				// Answered straight out of the cached snapshot: no client thread, no blocking.
				send(conn, new GetBank(request.getSequenceId(), store.snapshot()));
				break;
			default:
				send(conn, new ErrorResponse(request.getSequenceId(), "Unsupported request type"));
				break;
		}
	}

	@Override
	public void onError(WSConnection conn, Exception ex)
	{
		log.debug("Bank Bridge socket error conn=[{}]", conn == null ? null : conn.getLocalSocketAddress(), ex);

		// A null connection means the failure is the server's, not a peer's, and almost always a port
		// that is already in use.
		if (conn == null)
		{
			stopServer();
			// Try the next port once per port. If we have wrapped all the way back to PORT_MIN,
			// stop and wait for the scheduled ensureActive rather than spinning.
			if (this.nextPort != PORT_MIN)
			{
				ensureActive();
			}
		}
	}

	@Override
	public void onStart()
	{
		log.debug("Bank Bridge listening on 127.0.0.1:{}", server.getPort());
	}

	/** @return the bound port, or -1 if the socket is not currently listening. */
	public int getPort()
	{
		WSWebsocketServer s = this.server;
		return s == null || !serverActive.get() ? -1 : s.getPort();
	}

	private void send(WSConnection conn, Object message)
	{
		final String json = gson.toJson(message);
		executorService.submit(() -> {
			try
			{
				conn.send(json);
			}
			catch (RuntimeException e)
			{
				log.debug("Failed to send", e);
			}
		});
	}

	private boolean isOriginAllowed(String origin)
	{
		if (origin == null || origin.trim().isEmpty())
		{
			// Browsers always send Origin on a WebSocket handshake; something that omits it is not
			// a page, so there is no user intent behind it. An absent header reaches here as "",
			// and it is rejected explicitly rather than by leaning on URI("") parsing to a null
			// host further down.
			return false;
		}

		try
		{
			String host = new URI(origin).getHost();
			if (host == null)
			{
				return false;
			}
			host = host.toLowerCase(Locale.ROOT);
			return allowedHosts().contains(host);
		}
		catch (URISyntaxException e)
		{
			log.debug("Could not parse origin: {}", origin);
			return false;
		}
	}

	private Set<String> allowedHosts()
	{
		String extra = config.extraOrigins();
		if (extra == null || extra.trim().isEmpty())
		{
			return ALLOWED_ORIGIN_HOSTS;
		}

		Set<String> hosts = new HashSet<>(ALLOWED_ORIGIN_HOSTS);
		for (String s : extra.split(","))
		{
			String host = s.trim().toLowerCase(Locale.ROOT);
			if (!host.isEmpty())
			{
				hosts.add(host);
			}
		}
		return hosts;
	}

	private void stopServer()
	{
		try
		{
			if (this.server != null)
			{
				try
				{
					this.server.stop();
				}
				finally
				{
					this.server = null;
				}
			}
		}
		finally
		{
			this.serverActive.set(false);
		}
	}
}

package com.plaincandle.bankbridge;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * What this account has COMPLETED, as opposed to what it owns or how high its levels are.
 * <p>
 * A gear-planning site needs this because most access gates in the game are not levels: a route, a
 * quest-locked item or a diary shortcut is either unlocked or it is not, and no amount of reading
 * a bank will say which. Everything here is derived in {@link AccountUnlocks}, which is the only
 * file allowed to read a var.
 */
@Value
public class Unlocks
{
	/**
	 * Every quest this client knows, name to {@code "FINISHED"}, {@code "IN_PROGRESS"} or
	 * {@code "NOT_STARTED"}, sorted by name.
	 * <p>
	 * The whole vocabulary rather than the finished subset, and {@link AccountUnlocks} explains
	 * why at length: without it a consumer cannot tell a quest you have not done from one this
	 * client has no name for, and reads both as undone.
	 */
	Map<String, String> quests;

	/**
	 * Quest name to the game's own quest id, for every quest the client knows.
	 * <p>
	 * A second anchor beside the name, not a replacement for it: a consumer joins on the name
	 * because the wiki is name-keyed, and the id is what survives a rename. See
	 * {@link AccountUnlocks}.
	 */
	Map<String, Integer> questIds;

	/** Quest points. */
	int questPoints;

	/** Region name to the diary tiers completed there, in claim order. Every region is present. */
	Map<String, List<String>> diaries;

	/**
	 * Combat-achievement tier name to the raw tier varbit value. 2 means completed and 0 means not,
	 * observed live; an in-progress value is still unobserved, which is why this stays an integer.
	 */
	Map<String, Integer> combatAchievementTiers;

	/** The shape served when unlocks are unavailable or the player has turned them off. */
	static Unlocks empty()
	{
		return new Unlocks(
			Collections.<String, String>emptyMap(),
			Collections.<String, Integer>emptyMap(),
			0,
			Collections.<String, List<String>>emptyMap(),
			Collections.<String, Integer>emptyMap());
	}
}

